namespace ArgentSea.Pg;
public static class PgLoggingExtensions {   // public, unlike the internal Orleans counterpart
  // No enum of its own: every event id is taken from ArgentSea.LoggingExtensions.EventIdentifier, so COPY events share the core categories.
  // Each event is a LoggerMessage.Define delegate compiled once in the static constructor; EventId.Name equals the wrapper method name.
  void PgCopyCacheMiss(this ILogger logger, Type modelT)  // Information, id MapperCacheStatus (4): "No cached delegate was found for mapping type {modelT} to Pg row metadata; this is normal for the first execution."
  void PgCopyCacheHit(this ILogger logger, Type modelT)   // Debug, id MapperCacheStatus (4): "A cached delegate for mapping type {modelT} to Pg row metadata was found."
      // one level higher than the core mapping-cache events (miss Debug / hit Trace)
  void TraceCopyMapperProperty(this ILogger logger, string propertyName) // Trace, id MapperProcessTrace (5): "Copy mapper is now processing property {name}."
  void CreatedExpressionTreeForCopy(this ILogger logger, Type model, Expression codeBlock)
      // Debug, id ExpressionTreeCreation (1): "Compiled code to map model {model} to Pg COPY row values as:\r\n{code}."
      // renders codeBlock with a debug-view writer only when logger.IsEnabled(LogLevel.Debug), the level it logs at; logs model.ToString().
  void CopySqlStatements(this ILogger logger, string tableDef, string importerDef)
      // Debug, id CmdExecuted (8): "Copy mapper used a create table definition of: \r\n{tableDef} \r\n and used the copy import statment of:\r\n{copyDef}."
  // None of the wrappers except CreatedExpressionTreeForCopy adds an IsEnabled guard beyond the delegate's own.
}
